using System.Linq;
using UnityEditor;
using UnityEditor.Compilation;
public static class JojoPCompileState {
  public static string Run() {
    var assemblies = CompilationPipeline.GetAssemblies();
    var editor = assemblies.FirstOrDefault(a => a.name == "JojoP.Editor");
    var aot = assemblies.FirstOrDefault(a => a.name == "JojoP.AOT");
    return $"compiling={EditorApplication.isCompiling} editor={(editor!=null)} aot={(aot!=null)} editorOut={(editor?.outputPath ?? "")} ";
  }
}
